import json
from dataclasses import dataclass


@dataclass
class Item:
    name: str
    price: float
    qty: int = 1


def total(items: list[Item], discount: float = 0.0) -> float:
    """Sum of price * qty with an optional discount in percent."""
    if not 0 <= discount <= 100:
        raise ValueError(f"bad discount: {discount}")
    s = sum(i.price * i.qty for i in items)
    return round(s * (1 - discount / 100), 2)


def load(path: str) -> list[Item]:
    with open(path, encoding="utf-8") as f:
        return [Item(**row) for row in json.load(f)]


if __name__ == "__main__":
    print(total(load("cart.json"), discount=15))
